<?php declare(strict_types=1);
namespace Kulturhus\Verein;
use PDO;
require_once dirname(__DIR__, 2).'/Finance/Balance/BalancePoolStoredSources.php';
require_once __DIR__.'/PartnershipHoldingReview.php';
/** Review actual individuals and independent fiscal values, retaining every original voucher. */
final class PoolOriginalReview
{
 public function __construct(private PDO $db,private string $actor){}
 public function build(array $report,array $review,array $input,?array $previous=null):array{
  return BalanceReadSnapshot::run($this->db,function()use($report,$review,$input,$previous){
   $need=BalancePoolStoredSources::need(...);$need(!isset($report['period'])&&isset($report['whole_club_scope'])&&!isset($report['club_scope'])&&$review['opening_adjustments']===[]&&$review['current_adjustments']===[]&&empty($review['asset_tax_plans'])&&empty($review['own_intangible_sources'])&&empty($review['partnership_holdings']));
   $fields=['formed_year','population_document_id','population_complete','election_document_id','election_reason','election_confirmed','population','fiscal_opening','fiscal_depreciation','fiscal_closing','fiscal_document_id','fiscal_reason','fiscal_confirmed','book_document_id','book_reason','book_confirmed','book_journal_document_id','book_journal_reason','fiscal_journal_document_id','fiscal_journal_reason','journal_confirmed'];$need(!array_diff(array_keys($input),$fields));
   foreach(['population_complete','election_confirmed','fiscal_confirmed','book_confirmed','journal_confirmed'] as $key)$need(($input[$key]??null)==='1');foreach($fields as $key)if($key!=='population')$need(is_string($input[$key]??null));$need(is_array($input['population']??null));$formed=filter_var($input['formed_year'],FILTER_VALIDATE_INT);$need(in_array($formed,[2025,2026],true)&&$formed<=$report['year']);$stored=new BalancePoolStoredSources($this->db,$this->actor);$stored->actual($report);$actual=$stored->population($formed);$a=Permissions::actor($this->db,$this->actor);$e=new AssetValuationEvidence($this->db,$this->actor);$poolId=md5('original-pool:'.$a['club_id'].':'.$formed);$rows=[];$need(count($actual)===count($input['population']));
   foreach($actual as $id=>$o){$r=$input['population'][$id]??null;$need(is_array($r)&&!array_diff(array_keys($r),['quantity','depreciable_movable','independent_use','document_id','reason','confirmed'])&&($r['quantity']??null)==='1'&&($r['confirmed']??null)==='1'&&in_array($r['depreciable_movable']??null,['yes','no'],true)&&in_array($r['independent_use']??null,['yes','no'],true)&&is_string($r['document_id']??null)&&is_string($r['reason']??null));$row=array_intersect_key($o,array_flip(['item_id','invoice_id','invoice_ordinal','acquired_on','transaction_kind','quantity','net_cents','vat_cents','deductible_cents','basis_cents']));$rows[]=$row+['depreciable_movable'=>$r['depreciable_movable']==='yes','independent_use'=>$r['independent_use']==='yes','document'=>$e->reference($r['document_id']),'reason'=>$r['reason'],'confirmed'=>true];}
