   $register=['schema'=>1,'club_id'=>$a['club_id'],'pool_id'=>$poolId,'year'=>$report['year'],'opening_cents'=>PartnershipHoldingReview::amount($input['fiscal_opening']),'depreciation_cents'=>PartnershipHoldingReview::amount($input['fiscal_depreciation']),'closing_cents'=>PartnershipHoldingReview::amount($input['fiscal_closing']),'physical_departures'=>[],'document'=>$e->reference($input['fiscal_document_id']),'reason'=>$input['fiscal_reason'],'confirmed'=>true];$pool=PoolOriginalSources::calculate($s,$register,$previous['fiscal']['pool_proof']??null);$annual=$stored->annual($report,$s);$bookDoc=$e->reference($input['book_document_id']);$bookItems=[];
