   foreach($pool['eligible_items'] as $id){$o=$actual[$id];foreach($s['population'] as $r)if($r['item_id']===$id)$doc=$r['document'];if($report['year']===$formed){$need(count($o['binding']['entry_ids'])===1);$voucher=$o['binding']['entry_ids'][0];$links[]=['item_id'=>$id,'voucher_id'=>$voucher];$need(!isset($acqDocs[$voucher]));$acqDocs[$voucher]=$doc;}$dep=array_merge($dep,$annual[$id]['entry_ids']);}
   $journals=[];foreach(['books','fiscal'] as $side){$bookSide=$side==='books';$doc=$e->reference($input[$bookSide?'book_journal_document_id':'fiscal_journal_document_id']);$entries=$report['entries'];foreach($entries as &$row)$row['document']=$acqDocs[$row['id']]??(in_array($row['id'],$dep,true)?($bookSide?$bookDoc:$register['document']):$doc);unset($row);$j=['schema'=>1,'club_id'=>$a['club_id'],'pool_id'=>$poolId,'year'=>$report['year'],'period'=>BalancePeriod::calendar($report['year']),'chart'=>$report['accounts'],'result_account'=>$report['result_account'],'pool_account'=>$assetKeys[0],'depreciation_account'=>$depKeys[0],'opening'=>$report['opening'],'entries'=>$entries,'acquisition_links'=>$links,'depreciation_vouchers'=>$dep,'document'=>$doc,'reason'=>$input[$bookSide?'book_journal_reason':'fiscal_journal_reason'],'confirmed'=>true];$journals[$side]=$bookSide?PoolOriginalBookJournals::verify($bp,$j,$previous['books']??null):PoolOriginalJournals::verify($pool,$j,$previous['fiscal']??null);}
   BalancePoolOriginalValues::bind($report,[$poolId=>$journals]);$stored->evidence($journals);return $journals;
  });
 }
}
